DROP TABLE IF EXISTS `audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(60) COLLATE utf8mb4_persian_ci NOT NULL COMMENT 'نام جدول مرجع',
  `entity_id` bigint unsigned NOT NULL,
  `action` varchar(30) COLLATE utf8mb4_persian_ci NOT NULL COMMENT 'ثبت/ویرایش/حذف/تایید/رد/لغو/ارتقا_صف/منقضی',
  `description` text COLLATE utf8mb4_persian_ci NOT NULL,
  `performed_by` bigint unsigned DEFAULT NULL COMMENT 'NULL = سیستم/trigger',
  `ip_address` varchar(45) COLLATE utf8mb4_persian_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_audit_entity` (`entity_type`,`entity_id`),
  KEY `idx_audit_action` (`action`),
  KEY `idx_audit_created` (`created_at`),
  KEY `idx_audit_who` (`performed_by`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_persian_ci COMMENT='لاگ کامل عملیات سیستم — append-only';
