--
-- Table structure for table `business_slots`
--

DROP TABLE IF EXISTS `business_slots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `business_slots` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `business_id` bigint unsigned NOT NULL COMMENT 'FK منطقی',
  `business_name` varchar(200) COLLATE utf8mb4_persian_ci NOT NULL COMMENT 'snapshot از businesses.name',
  `day_of_week` tinyint unsigned NOT NULL COMMENT '0=شنبه 1=یکشنبه ... 6=جمعه',
  `time_slot` char(5) COLLATE utf8mb4_persian_ci NOT NULL COMMENT 'HH:MM',
  `max_capacity` tinyint unsigned NOT NULL DEFAULT '1',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_slot` (`business_id`,`day_of_week`,`time_slot`),
  KEY `idx_bs_business` (`business_id`),
  KEY `idx_bs_day` (`day_of_week`),
  CONSTRAINT `chk_bs_time` CHECK (regexp_like(`time_slot`,_utf8mb4'^([01][0-9]|2[0-3]):[0-5][0-9]$')),
  CONSTRAINT `chk_day_of_week` CHECK ((`day_of_week` between 0 and 6))
) ENGINE=InnoDB AUTO_INCREMENT=757 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_persian_ci COMMENT='ساعات کاری و اسلات‌های کسب‌وکار';
/*!40101 SET character_set_client = @saved_cs_client */;

