CREATE TABLE `notification_outbox` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `idempotency_key` varchar(120) COLLATE utf8mb4_persian_ci DEFAULT NULL COMMENT 'جلوگیری از ارسال تکراری — NULL=بدون idempotency check',
  `user_id` bigint unsigned NOT NULL,
