  `title` varchar(200) COLLATE utf8mb4_persian_ci NOT NULL,
  `body` text COLLATE utf8mb4_persian_ci NOT NULL,
  `related_entity_type` varchar(60) COLLATE utf8mb4_persian_ci DEFAULT NULL,
  `related_entity_id` bigint unsigned DEFAULT NULL,
  `status` enum('pending','processing','delivered','failed') COLLATE utf8mb4_persian_ci NOT NULL DEFAULT 'pending',
  `attempt_count` tinyint unsigned NOT NULL DEFAULT '0',
  `next_retry_at` datetime DEFAULT NULL COMMENT 'exponential backoff — NULL=فوری',
  `processed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'تاریخ آخرین تغییر status — برای تشخیص worker گیر کرده',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_outbox_idempotency` (`idempotency_key`),
  KEY `idx_outbox_pending` (`status`,`next_retry_at`),
  KEY `idx_outbox_created` (`created_at`),
  KEY `idx_outbox_user` (`user_id`),
  CONSTRAINT `chk_outbox_type` CHECK ((`type` in (_utf8mb4'رزرو_موفق',_utf8mb4'لغو_نوبت',_utf8mb4'یادآوری',_utf8mb4'ثبت_صف',_utf8mb4'ارتقا_صف',_utf8mb4'تایید_کسب‌وکار',_utf8mb4'رد_کسب‌وکار')))
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_persian_ci COMMENT='صندوق خروجی async — SP/Trigger به اینجا می‌نویسند، worker تحویل می‌دهد';
