--
-- Table structure for table `notifications`
--

DROP TABLE IF EXISTS `notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notifications` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL COMMENT 'FK منطقی',
  `user_phone` varchar(11) COLLATE utf8mb4_persian_ci NOT NULL COMMENT 'snapshot برای SMS',
  `type` varchar(30) COLLATE utf8mb4_persian_ci NOT NULL COMMENT 'مقادیر مجاز: chk_notif_type — افزودن نوع جدید فقط با ALTER CHECK (INSTANT)',
  `title` varchar(200) COLLATE utf8mb4_persian_ci NOT NULL,
  `body` text COLLATE utf8mb4_persian_ci NOT NULL,
  `related_entity_type` varchar(60) COLLATE utf8mb4_persian_ci DEFAULT NULL COMMENT 'برای deep link در frontend',
  `related_entity_id` bigint unsigned DEFAULT NULL COMMENT 'برای deep link در frontend',
  `is_read` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_notif_user_date` (`user_id`,`created_at`),
  KEY `idx_notif_user_unread` (`user_id`,`is_read`,`created_at`),
  KEY `idx_notif_type` (`type`),
  CONSTRAINT `chk_notif_type` CHECK ((`type` in (_utf8mb4'رزرو_موفق',_utf8mb4'لغو_نوبت',_utf8mb4'یادآوری',_utf8mb4'ثبت_صف',_utf8mb4'ارتقا_صف',_utf8mb4'تایید_کسب‌وکار',_utf8mb4'رد_کسب‌وکار')))
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_persian_ci COMMENT='صندوق اعلان کاربران — توسط async worker پر می‌شود';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `notifications`
--

